<script setup lang="ts">
import { Head, Link } from '@inertiajs/vue3'; import { ArrowLeft, CalendarDays, Clock3, Dumbbell, Pencil, Phone } from '@lucide/vue'; import { Button } from '@/components/ui/button';
type Trainer={id:number;name:string;specialty:string|null;phone:string|null;created_at:string|null;updated_at:string|null}; const props=defineProps<{trainer:Trainer}>();
function date(v:string|null){return v?new Intl.DateTimeFormat('id-ID',{day:'2-digit',month:'long',year:'numeric'}).format(new Date(v)):'—'} function initials(n:string){return n.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()}
</script>
