um">{{props.trainer.specialty || '—'}}</p></div><div class="flex gap-3"><Phone class="size-4 text-muted-foreground"/><div><p class="text-xs text-muted-foreground">Phone</p><p class="mt-1 text-sm font-medium">{{props.trainer.phone || '—'}}</p></div></div></div></section><section class="rounded-2xl border bg-card p-5 shadow-sm"><div class="flex items-center gap-2"><CalendarDays class="size-4 text-primary"/><h3 class="font-semibold">Record information</h3></div><div class="mt-5 space-y-4"><div><p class="text-xs text-muted-foreground">Created</p><p class="mt-1 text-sm font-medium">{{date(props.trainer.created_at)}}</p></div><div class="flex gap-3"><Clock3 class="size-4 text-muted-foreground"/><div><p class="text-xs text-muted-foreground">Last updated</p><p class="mt-1 text-sm font-medium">{{date(props.trainer.updated_at)}}</p></div></div></div></section></div></div></template>